const n = p.number; const status = String(p.to || '');
const lines = {
  PAID: [['jeff', `${n} is paid. It's real now.`], ['justin', `${n} paid.`]],
  BLANKS_ORDERED: [['jeff', `Blanks are on the way for ${n}. Watch the dock.`]],
